  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this analysis — are you trying to maximize the total value of Carelland's exports (i.e., the value of domestically produced goods sold on the world market), or something else such as maximizing net trade balance or minimizing imports?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

